SourceCode.Declaration:
/// <summary>
/// Which stores (warehouses) a supervisor manages in the Stock count control center - the form
/// shows a supervisor only those stores' counts; a user with no row here sees every store.
/// StageJournalCounts sends counts against D365FO counting journals in that store through the
/// control center too, instead of straight into the journal.
/// </summary>
public class HSMobileOpsCountStore extends common
{
}

Method.Source:
/// <summary>
/// Whether counts against counting journals in this store are reviewed in the control center.
/// </summary>
public static boolean stagesJournalCounts(InventLocationId _store)
{
    HSMobileOpsCountStore store;

    select firstonly RecId from store
        where store.InventLocationId   == _store
           && store.StageJournalCounts == NoYes::Yes;
    return store.RecId != 0;
}
